/* @lc app=leetcode id=3352 lang=kotlin */ class Solution { fun countKReducibleNumbers(s: String, k: Int): Int = 1_000_000_007L.let { M -> s.length.let { n -> IntArray(n + 2).also { f -> (2..n + 1).forEach { c -> f[c] = 1 + f[Integer.bitCount(c)] } }.let { f -> (0..n).fold(Array(n + 1) { LongArray(n + 1) }) { t, i -> t.also { r -> (0..i).forEach { j -> r[i][j] = if (j == 0 || j == i) 1L else (t[i - 1][j - 1] + t[i - 1][j]) % M } } }.let { C -> ((1..n).filter { 1 + f[it] <= k }.sumOf { c -> s.indices.fold(0 to 0L) { (ones, acc), i -> if (s[i] == '1') (ones + 1) to (acc + (if (c - ones in 0..n - 1 - i) C[n - 1 - i][c - ones] else 0L)) else ones to acc }.second } % M).toInt() } } } } }